class Client
  def setup_body(len)
    reject_payload if @limit && len > @limit
    @body.read(len)
  end

  def write_chunk(str)
    reject_payload if @limit && @size + str.bytesize > @limit
    @size += @body.write(str)
  end

  def reject_payload
    @limit_exceeded = true
    @buffer = nil
    @body = EmptyBody
    @error_status_code = 413
    @env[HTTP_CONNECTION] = 'close'
    raise HttpParserError, "Payload Too Large"
  end
end

